<?php declare(strict_types=1);
namespace Kulturhus\Native\Pos;
use PDO;
use Kulturhus\Native\Shared\{SecretBox,Db};
use Kulturhus\Native\Integration\{Accounts,ManagerBridge};
use Kulturhus\Native\Payments\{Money,SumUp,PayPal};
use Kulturhus\Native\Web\Html;
use Kulturhus\Verein\{Finance,EventVouchers,Permissions};
final class Web
{
    public function __construct(private PDO $db,private Register $register,private string $actor,private string $csrf,private ?\Kulturhus\Verein\WebsiteCalendar $calendar=null){}
    private function client(string $provider):SumUp|PayPal
    {$key=getenv('KH_NATIVE_PRIVATE_KEY_FILE')?:dirname(__DIR__,3).'/.local/native-cms-integration/private.key';$a=Permissions::actor($this->db,$this->actor);$c=(new Accounts($this->db,SecretBox::fromFile($key)))->get(ManagerBridge::clubKey($a['club_id']),$provider);return $provider==='sumup'?new SumUp($c):new PayPal($c);}
    public function action(array $post):array
    {
        if(!is_string($post['csrf']??null)||!hash_equals($this->csrf,$post['csrf']))throw new \DomainException('Kassenformular abgelaufen.');
        $text=static fn($k)=>is_string($post[$k]??null)?$post[$k]:'';$op=$text('operation');$shift=$text('shift');$sale=$text('sale');$payment=$text('payment');
        if(in_array($op,['scan','check-in'],true)){
            $this->register->shift($shift);$code=\Kulturhus\Native\Communication\Content::text($text('ticket_code'),160,true);$_SESSION['pos_scan']=['shift'=>$shift,'code'=>$code];
            if($op==='scan')$this->register->scan($shift,$code);else $this->register->checkIn($shift,$code,(int)$text('version'));
        }
        elseif($op==='product'){$post['price']=Money::decimal(self::inputMoney($text('price')));$this->register->saveProduct($post,(int)$text('version'));}
        elseif($op==='open')$shift=$this->register->open($text('event'),$text('account'),self::inputMoney($text('opening')),$this->station($post));
        elseif($op==='station-settings'){if(array_diff(['station_name','reader','station_version'],array_keys($post))||!preg_match('/^(0|[1-9][0-9]{0,9})$/D',$text('station_version')))throw new \DomainException('Kasseneinrichtung vollständig prüfen.');$this->register->configure($shift,(int)$text('station_version'),$this->station($post));}
        elseif($op==='cart-manual'){$qty=$text('manual_quantity');if(!preg_match('/^[1-9][0-9]{0,2}$/D',$qty))throw new \DomainException('Artikelanzahl prüfen.');$sale=$this->register->cart($shift,[['id'=>$text('manual_product'),'quantity'=>(int)$qty]],0,$text('request_key'))['id'];}
        elseif($op==='cart'){$lines=json_decode($text('lines'),true,64,JSON_THROW_ON_ERROR);if(!is_array($lines))throw new \DomainException('Warenkorb prüfen.');$sale=$this->register->cart($shift,$lines,self::inputMoney($text('discount')?:'0'),$text('request_key'))['id'];}
        elseif($op==='benefit')$this->register->benefit($sale,(int)$text('version'),strtoupper(trim($text('benefit_code'))),$text('product'),(int)$text('quantity'));
        elseif($op==='tender'){
            $mode=$text('tender_mode');$cash=self::inputMoney($text('cash')?:'0');$received=self::inputMoney($text('received')?:'0');$voucher=self::inputMoney($text('voucher_amount')?:'0');$code=strtoupper(trim($text('voucher_code')));$method=$text('method');
            if($mode!==''){
                if(!in_array($mode,['cash','card','voucher','mixed'],true))throw new \DomainException('Bitte Bar, Karte oder Gutschein auswählen.');
                $original=$this->register->sale($sale);$this->register->shift($original['shift_id']);
                if($mode==='cash'){$cash=(int)$original['total_cents'];$voucher=0;$code='';}
                elseif($mode==='card'){if(!in_array($method,['sumup-reader','sumup-tap','paypal'],true))throw new \DomainException('Bitte den Zahlungsweg auswählen.');$cash=$received=$voucher=0;$code='';}
                elseif($mode==='voucher'){
                    $scan=$this->register->scan($original['shift_id'],$code);
                    if(($scan['kind']??'')!=='value-voucher')throw new \DomainException('Bitte einen Wertgutschein verwenden. Persönliche Vorteile werden gesondert eingelöst.');
                    $_SESSION['pos_scan']=['shift'=>$original['shift_id'],'code'=>$code];
                    if(($scan['remaining_cents']??0)<$original['total_cents'])throw new \DomainException('Das Gutscheinguthaben reicht nicht für den ganzen Einkauf. Bitte „Gemischt bezahlen“ öffnen; das geprüfte Guthaben ist dort vorbelegt.');
                    $voucher=(int)$original['total_cents'];$cash=$received=0;
                }
            }
            Db::atomic($this->db,function()use($sale,$text,$cash,$code,$voucher,$received,$mode,$method,&$payment):void{
                $paid=$this->register->tender($sale,(int)$text('version'),$cash,$code,$voucher,$received);
                if($mode==='card'&&$paid['state']==='payment')$payment=$this->register->attempt($sale,$method)['id'];
            });
        }
        elseif($op==='attempt')$payment=$this->register->attempt($sale,$text('method'))['id'];
        elseif($op==='cancel-attempt'){$this->register->cancelPrepared($payment);$payment='';}
        elseif(in_array($op,['start','native-info','native-start'],true)){
            $attempt=$this->register->payment($payment);$native=$op!=='start';
            if($native){
                if(!in_array($attempt['method'],['sumup-tap','sumup-reader'],true))throw new \DomainException('Nativer SumUp-Weg erforderlich.');
                $a=Permissions::actor($this->db,$this->actor);$key=getenv('KH_NATIVE_PRIVATE_KEY_FILE')?:dirname(__DIR__,3).'/.local/native-cms-integration/private.key';$account=(new Accounts($this->db,SecretBox::fromFile($key)))->get(ManagerBridge::clubKey($a['club_id']),'sumup');
                if($op==='native-info'){if($attempt['state']!=='prepared')throw new \DomainException('Versuch bereits begonnen. Ergebnis unabhängig prüfen.');$started=$attempt;}else{$started=$this->register->start($payment,static fn($a)=>['external_id'=>$a['reference'],'native'=>true]);if($started['state']!=='pending')throw new \DomainException('Nativer Versuch nicht startbar.');}
                return ['native'=>['attempt'=>$payment,'reference'=>$started['reference'],'amount_cents'=>(int)$started['amount_cents'],'currency'=>'EUR','merchant_code'=>$account['merchant_code'],'method'=>$started['method']]];
            }
            if($attempt['method']==='paypal'){$api=$this->client('paypal');$this->register->start($payment,fn($a)=>$api->create($a));}
            elseif($attempt['method']==='sumup-reader'){$original=$this->register->sale($attempt['sale_id']);$configured=$this->reader($original['shift_id']);$reader=$text('reader');if(!$configured)throw new \DomainException('Bitte zuerst für diese Kasse einen Kartenleser auswählen.');if($reader!==$configured['id'])throw new \DomainException('Der Kartenleser dieser Kasse wurde geändert. Bitte die Zahlung neu öffnen.');$api=$this->client('sumup');$this->register->start($payment,fn($a)=>$api->reader($a,$reader),static function(array $station)use($reader,$configured):void{if($station['reader_id']!==$reader||$station['merchant_code']!==$configured['merchant_code'])throw new \DomainException('Der Kartenleser dieser Kasse wurde geändert. Bitte die Zahlung neu öffnen.');});}
            else throw new \DomainException('Tap to Pay in der nativen Kassen-App starten.');
        }
        elseif($op==='capture'){$a=$this->register->payment($payment);if($a['method']!=='paypal')throw new \DomainException('PayPal-Versuch erforderlich.');$this->client('paypal')->capture($a);$this->register->verify($payment,fn($p)=>$this->client('paypal')->verify($p));}
        elseif($op==='verify'){$a=$this->register->payment($payment);$provider=$a['method']==='paypal'?'paypal':'sumup';$api=$this->client($provider);$this->register->verify($payment,fn($p)=>$api instanceof SumUp?$api->reconcile($p):$api->verify($p));if($this->register->payment($payment)['state']==='failed')$payment='';}
        elseif($op==='cancel')$this->register->cancel($sale,(int)$text('version'));
        elseif($op==='close')$this->register->close($shift,self::inputMoney($text('counted')));
        elseif($op==='refund')$this->register->refund($sale,$text('reason'),fn($proof,$sale)=>$this->client($proof['provider'])->refundConfirmed($proof,substr(hash('sha256','pos-refund:'.$sale),0,32)));
        elseif($op==='refund-verify')$this->register->reconcileRefund($sale,function($proof,$sale,$checkpoint)use($text){$api=$this->client($proof['provider']);if($proof['provider']==='sumup')return $api->verifyRefund($proof);$attempt=Db::run($this->db,"SELECT external_id FROM pos_attempts WHERE club_id=? AND sale_id=? AND method='paypal' AND state='verified'",[Permissions::actor($this->db,$this->actor)['club_id'],$sale])->fetch();$refundId=$checkpoint['external_id']??$text('refund_id');if($refundId==='')$refundId=$text('refund_id');return $api->verifyRefund($proof,substr(hash('sha256','pos-refund:'.$sale),0,32),$refundId,$attempt['external_id']??'');});
        else throw new \DomainException('Unbekannte Kassenaktion.');
        return ['shift'=>$shift,'sale'=>$sale,'payment'=>$payment];
    }
    private function form(string $operation,array $fields=[]):string
    {$h='<form method="post">'.Html::hidden('csrf',$this->csrf).Html::hidden('operation',$operation);foreach($fields as $k=>$v)$h.=Html::hidden($k,(string)$v);return $h;}
    private static function inputMoney(string $amount):int{return Money::cents(str_replace(',', '.',trim($amount)));}
    private function money(int $c):string{return number_format($c/100,2,',','.').' €';}
    private static function state(string $state):string
    {return match($state){'cart'=>'Offen','payment'=>'Zahlung ausstehend','paid','verified'=>'Bezahlt','refunded'=>'Erstattet','cancelled'=>'Abgebrochen','open'=>'Geöffnet','closed'=>'Abgeschlossen','prepared'=>'Bereit zum Start','processing'=>'Zahlung gestartet','pending'=>'Bestätigung ausstehend','uncertain'=>'Zahlungsstand prüfen','failed'=>'Nicht abgeschlossen','confirmed'=>'Bestätigt',default=>'Bitte prüfen'};}
    private static function method(string $method):string
    {return match($method){'sumup-reader'=>'Kartenzahlung am Lesegerät','sumup-tap'=>'Kontaktlos mit diesem Gerät','paypal'=>'PayPal',default=>'Kartenzahlung'};}
    private function readers():array
    {
        try{$a=Permissions::actor($this->db,$this->actor);$key=getenv('KH_NATIVE_PRIVATE_KEY_FILE')?:dirname(__DIR__,3).'/.local/native-cms-integration/private.key';$c=(new Accounts($this->db,SecretBox::fromFile($key)))->get(ManagerBridge::clubKey($a['club_id']),'sumup');return ['merchant_code'=>$c['merchant_code'],'choices'=>Accounts::readers($c)];}catch(\DomainException|\RuntimeException){return ['merchant_code'=>'','choices'=>[]];}
    }
    private function station(array $post):array
    {
        foreach(['station_name','reader']as$field)if(array_key_exists($field,$post)&&!is_string($post[$field]))throw new \DomainException('Kasseneinrichtung vollständig prüfen.');$sources=$this->readers();$reader=$post['reader']??'';if($reader!==''&&!isset($sources['choices'][$reader]))throw new \DomainException('Bitte einen eingerichteten Kartenleser für diese Kasse auswählen.');return ['name'=>is_string($post['station_name']??null)?$post['station_name']:'','reader_id'=>$reader,'reader_name'=>$sources['choices'][$reader]??'','merchant_code'=>$reader!==''?$sources['merchant_code']:''];
    }
    private function reader(string $shift):array
    {
        $station=$this->register->shift($shift);$sources=$this->readers();$id=$station['reader_id'];return $id!==''&&$sources['merchant_code']===$station['merchant_code']&&isset($sources['choices'][$id])?['id'=>$id,'name'=>$sources['choices'][$id],'merchant_code'=>$sources['merchant_code']]:[];
    }
    private function stationFields(array $shift=[]):string
    {
        $sources=$this->readers();$choices=[''=>'Kein fest zugeordneter Kartenleser']+$sources['choices'];$selected=$shift['reader_id']??'';if($selected!==''&&!isset($choices[$selected]))$choices[$selected]=($shift['reader_name']?:'Bisheriger Kartenleser').' · bitte neu auswählen';
        return Html::input('station_name','Name dieser Kasse',$shift['station_name']??'','text','required maxlength="160" placeholder="z. B. Einlass oder Theke"').Html::select('reader','Kartenleser dieser Kasse',$choices,$selected).(!$sources['choices']?'<p>Für Kartenzahlungen kannst du einmalig <a href="/vereinsverwaltung/?view=settings&amp;tab=api#connections">Kartenleser einrichten</a> und anschließend dieser Kasse zuordnen.</p>':'');
    }
    private function tenderForm(array $fields,array $sale,?array $scan):string
    {
        $amount=Money::decimal((int)$sale['total_cents']);$voucher=($scan['kind']??'')==='value-voucher'?min((int)$scan['remaining_cents'],(int)$sale['total_cents']):0;$code=$voucher?($scan['code']??''):'';$cash=Money::decimal((int)$sale['total_cents']-$voucher);
        $h='<section class="pos-payment-choices"><h3>Wie wird bezahlt?</h3><details name="pos-payment-choice" open><summary>Bar bezahlen</summary>'.$this->form('tender',$fields+['tender_mode'=>'cash']).'<p>Zu zahlen: <strong>'.$this->money((int)$sale['total_cents']).'</strong></p>'.Html::input('received','Bargeld erhalten',$amount,'text','inputmode="decimal" required data-pos-received data-pos-total="'.(int)$sale['total_cents'].'"').'<output class="pos-change" data-pos-change aria-live="polite">Rückgeld: 0,00 €</output><button>Barzahlung abschließen</button></form></details>';
        $h.='<details name="pos-payment-choice"><summary>Karte oder PayPal</summary>'.$this->form('tender',$fields+['tender_mode'=>'card']).Html::select('method','Zahlungsweg',['sumup-reader'=>'Kartenleser','sumup-tap'=>'Kontaktlos mit diesem Gerät','paypal'=>'PayPal'],'sumup-reader').'<button>Weiter zur Kartenzahlung</button></form></details>';
        $h.='<details name="pos-payment-choice"><summary>Mit Wertgutschein bezahlen</summary>'.$this->form('tender',$fields+['tender_mode'=>'voucher']).Html::input('voucher_code','Wertgutschein-Code',$code,'text','required autocomplete="off" spellcheck="false"').'<p>Reicht das Guthaben aus, wird der Einkauf direkt bezahlt. Ein Restguthaben bleibt auf dem Gutschein.</p><button>Gutschein prüfen und einlösen</button></form></details>';
        $h.='<details name="pos-payment-choice" data-pos-mixed><summary>Gemischt bezahlen</summary>'.$this->form('tender',$fields+['tender_mode'=>'mixed']).'<div class="pos-fields">'.Html::input('cash','Davon bar',$cash,'text','inputmode="decimal"').Html::input('received','Bargeld erhalten',$cash,'text','inputmode="decimal"').Html::input('voucher_code','Wertgutschein-Code',$code).Html::input('voucher_amount','Davon Wertgutschein',Money::decimal($voucher),'text','inputmode="decimal"').'</div><p>Der verbleibende Betrag wird anschließend per Karte oder PayPal bezahlt.</p><button>Zahlungsaufteilung übernehmen</button></form></details></section>';
        return $h;
    }
    public function render(array $query,string $error=''):string
    {
        $shift=is_string($query['shift']??null)?$query['shift']:'';$saleId=is_string($query['sale']??null)?$query['sale']:'';$payment=is_string($query['payment']??null)?$query['payment']:'';$e=Html::e(...);
        $h='<header class="pos-header"><a href="/vereinsverwaltung/?view=portal&amp;tab=vouchers">← Vereinsmanager</a><h1>Touch-Kasse</h1></header><main id="main"><p class="pos-error" role="alert">'.$e($error).'</p>';
        if(isset($query['receipt'])){$receipt=$this->register->receipt($saleId);$h.=$this->receipt($receipt);return $this->shell($h.'</main>');}
        $h.='<nav class="pos-shifts" aria-label="Kassen">';foreach($this->register->shifts() as $s)$h.='<a href="?view=pos&amp;shift='.$e($s['id']).'"'.($s['id']===$shift?' aria-current="page"':'').'>'.$e($s['station_name'].' · '.$s['title'].' · '.self::state($s['state'])).'</a>';$h.='</nav>';
        if($shift){$s=$this->register->shift($shift);$balance=$this->register->shiftSummary($shift);$h.='<section class="pos-panel" data-pos-shift-balance><h2>'.$e($s['station_name']).'</h2><p>Handkasse: '.$e($s['cash_account_name']).' · '.self::state($s['state']).'</p><p>Bar-Sollbestand: <strong>'.$this->money($balance['expected_cents']).'</strong> · inklusive '.$this->money($balance['opening_cents']).' Anfangsbestand</p>'.($balance['counted_cents']!==null?'<p>Beim Abschluss gezählt: '.$this->money($balance['counted_cents']).'</p>':'').'</section>';if($this->register->canManage()&&$s['state']==='open')$h.='<details class="pos-panel" id="pos-station-settings"><summary>Diese Kasse einrichten</summary>'.$this->form('station-settings',['shift'=>$shift,'station_version'=>$s['station_version']]).$this->stationFields($s).'<button>Kasseneinrichtung speichern</button></form></details>';$products=$this->register->products($s['event_id']);$sale=$saleId?$this->register->sale($saleId):null;if($sale&&$sale['shift_id']!==$shift)throw new \DomainException('Verkauf gehört zu einer anderen Kasse.');
            $scan=null;$scanCode='';if(($_SESSION['pos_scan']['shift']??null)===$shift&&is_string($_SESSION['pos_scan']['code']??null)){$scanCode=$_SESSION['pos_scan']['code'];try{$scan=$this->register->scan($shift,$scanCode);}catch(\DomainException){}}
            $h.='<details class="pos-panel ticket-scan"'.($scanCode!==''?' open':'').'><summary>QR prüfen · Einlass / Gutschein</summary>'.$this->form('scan',['shift'=>$shift]).Html::input('ticket_code','QR-Code oder Gutscheincode',$scanCode,'text','required autocomplete="off" spellcheck="false" data-ticket-code').'<div class="ticket-actions"><button>Prüfen</button><button class="secondary" type="button" data-ticket-camera>QR scannen</button></div></form><video data-ticket-video hidden playsinline muted aria-label="QR-Kamera"></video><button type="button" data-ticket-camera-stop hidden>Kamera schließen</button><p data-ticket-camera-status role="status"></p>';
            if($scan){$kind=$scan['kind'];$label=match($kind){'admission'=>'Eintrittsticket','value-voucher'=>'Wertgutschein',default=>'Persönlicher Vereinsgutschein'};$h.='<p><strong>'.$label.'</strong></p>';
                if($kind==='admission'){$h.='<p>'.$e($scan['buyer_name']).' · '.($scan['status']==='test'?'Testticket · Kein Einlass':($scan['status']==='checked_in'?'Bereits eingelassen':($scan['payment_status']==='paid'&&$scan['status']==='valid'?'Für den Einlass gültig':'Nicht freigegeben'))).'</p>';if($scan['status']==='valid'&&$scan['payment_status']==='paid')$h.=$this->form('check-in',['shift'=>$shift,'ticket_code'=>$scanCode,'version'=>$scan['version']]).'<button>Einlass bestätigen</button></form>';}
                elseif($kind==='value-voucher')$h.='<p>Restguthaben <strong>'.$this->money($scan['remaining_cents']).'</strong></p><p>'.($scan['status']==='test'?'Testgutschein · Nicht einlösbar':($scan['status']==='active'?'Gültig':'Gesperrt')).'</p>';
                else $h.='<p>'.$e($scan['label']).' · '.EventVouchers::display($scan['remaining'],$scan['unit']).'</p>';
            }$h.='</details>';
            if($sale){$h.='<section class="pos-panel"><h2>Warenkorb · '.$e(self::state($sale['state'])).'</h2><ul>';foreach($sale['payload']['lines'] as $p)$h.='<li>'.$p['quantity'].' × '.$e($p['label']).' <strong>'.$this->money($p['amount_cents']).'</strong></li>';$h.='</ul><p>Rabatt '.$this->money($sale['payload']['discount_cents']).' · Mitgliedervorteil '.$this->money($sale['payload']['benefit_cents']).'</p><h3>Gesamt '.$this->money($sale['total_cents']).'</h3>';
                $fields=['shift'=>$shift,'sale'=>$saleId,'version'=>$sale['version']];
                if($sale['state']==='cart'){
                    $h.=$this->tenderForm($fields,$sale,$scan);
                    $choices=[];foreach($sale['payload']['lines'] as $line)$choices[$line['id']]=$line['label'];$h.='<details><summary>Persönlichen Mitgliedervorteil einlösen</summary>'.$this->form('benefit',$fields).Html::input('benefit_code','Persönlicher Gutscheincode').Html::select('product','Passender Artikel',$choices,'').Html::input('quantity','Stückzahl',1,'number','min="1" max="100"').'<button>Vorteil prüfen und anwenden</button></form></details>';
                }
                if($sale['state']==='payment'){
                    if(!$payment)$h.=$this->form('attempt',$fields).Html::select('method','Zahlungsweg',['sumup-reader'=>'Kartenleser','sumup-tap'=>'Kontaktlos mit diesem Gerät','paypal'=>'PayPal'],'sumup-reader').'<button>Zahlungsweg öffnen</button></form>';
                    if($payment){$a=$this->register->payment($payment);if($a['sale_id']!==$saleId)throw new \DomainException('Zahlungsversuch gehört zu anderem Verkauf.');$h.='<article class="pos-panel"><h3>'.$e(self::method($a['method'])).' · '.$this->money((int)$a['amount_cents']).'</h3><p>Status: '.$e(self::state($a['state'])).'</p><details><summary>Technische Details</summary><p>'.$e($a['reference']).'</p></details>';
                        if($a['state']==='prepared'){
                            $h.=$this->form('cancel-attempt',$fields+['payment'=>$payment]).'<button class="secondary">Anderen Zahlungsweg wählen</button></form>';
                            if($a['method']!=='sumup-tap'){$reader=$a['method']==='sumup-reader'?$this->reader($shift):[];$h.=$this->form('start',$fields+['payment'=>$payment]).($a['method']==='sumup-reader'?($reader?'<p>Kartenleser: <strong>'.$e($reader['name']).'</strong></p>'.Html::hidden('reader',$reader['id']):'<p>Für diese Kasse ist kein gültiger Kartenleser ausgewählt. <a href="#pos-station-settings">Diese Kasse einrichten</a></p>'):'').'<button'.($a['method']==='sumup-reader'&&!$reader?' disabled':'').'>'.($a['method']==='paypal'?'PayPal-Zahlung starten':'Kartenzahlung starten').'</button></form>';}
                            if($a['method']!=='paypal')$h.='<button type="button" data-native-payment="'.$e($payment).'" data-native-method="'.$e($a['method']).'" data-csrf="'.$e($this->csrf).'">Mit diesem Gerät bezahlen</button><p data-native-notice>Für die Zahlung mit diesem Gerät muss die Kassen-App eingerichtet sein.</p>';
                        }
                        $result=$a['result_json']?json_decode($a['result_json'],true):[];if(!empty($result['approval_url']))$h.='<a class="button" href="'.$e($result['approval_url']).'" target="_blank" rel="noopener">PayPal-Freigabe öffnen</a>';
                        if($a['method']==='paypal'&&$a['external_id'])$h.=$this->form('capture',$fields+['payment'=>$payment]).'<button>PayPal-Zahlung abschließen</button></form>';
                        if(in_array($a['state'],['failed','cancelled'],true))$h.='<a class="button" href="?view=pos&amp;shift='.$e($shift).'&amp;sale='.$e($saleId).'">Zahlungsweg auswählen</a></article>';else $h.=$this->form('verify',$fields+['payment'=>$payment]).'<button>Zahlungsstand aktualisieren</button></form><p>Bei unklarem Ergebnis keine neue Zahlung starten.</p></article>';
                    }
                }
                if(in_array($sale['state'],['cart','payment'],true))$h.=$this->form('cancel',$fields).'<button class="secondary">Unbezahlten Verkauf verwerfen</button></form>';
                if(in_array($sale['state'],['paid','refunded'],true)){$h.='<a class="button" href="?view=pos&amp;shift='.$e($shift).'&amp;sale='.$e($saleId).'&amp;receipt=1">Originalbeleg anzeigen & drucken</a>';if($sale['state']==='paid'&&$this->register->canManage()){$refund=$this->register->refundStatus($saleId);if($refund){$h.='<section class="panel"><h3>Rückzahlung prüfen</h3><p>'.Html::e(self::state($refund['state']).' · '.$refund['reason']).'</p><p>Nur Anbieterstatus lesen. Keine erneute Rückzahlung auslösen.</p>'.$this->form('refund-verify',$fields).Html::input('refund_id','PayPal-Erstattungskennung (nur falls nicht abrufbar)','','text').'<button>Rückzahlung unabhängig abgleichen</button></form></section>';}else $h.='<details><summary>Verkauf nachvollziehbar stornieren</summary>'.$this->form('refund',$fields).Html::input('reason','Stornogrund','','text','required').'<button>Vollständige Rückzahlung / Storno ausführen</button></form></details>';}}
                $h.='<a class="button secondary" href="?view=pos&amp;shift='.$e($shift).'">Nächster Warenkorb</a></section>';
            }elseif($s['state']==='open'){
                $h.='<div class="pos-layout"><section><h2>Artikeltasten</h2><div class="pos-products">';foreach($products as $p)$h.='<button type="button" class="pos-product" disabled data-product="'.$e($p['id']).'" data-label="'.$e($p['label']).'" data-price="'.$p['price_cents'].'" style="--article-color:'.$e($p['color']).'"><strong>'.$e($p['label']).'</strong><span>'.$this->money((int)$p['price_cents']).'</span></button>';$manual=[];foreach($products as$p)$manual[$p['id']]=$p['label'].' · '.$this->money((int)$p['price_cents']);$h.='</div><noscript>'.$this->form('cart-manual',['shift'=>$shift,'request_key'=>bin2hex(random_bytes(16))]).Html::select('manual_product','Artikel',$manual,'').Html::input('manual_quantity','Anzahl',1,'number','required min="1" max="100"').'<button>Warenkorb erstellen</button></form></noscript></section><aside class="pos-panel"><h2>Warenkorb</h2><div id="pos-cart" aria-live="polite">Artikel antippen.</div>'.$this->form('cart',['shift'=>$shift,'request_key'=>bin2hex(random_bytes(16))]).'<input type="hidden" id="pos-lines" name="lines" value="[]">'.($this->register->canManage()?Html::input('discount','Rabatt gesamt','0','text','inputmode="decimal"'):Html::hidden('discount','0')).'<button id="pos-save-cart" disabled>Warenkorb übernehmen</button></form></aside></div>';
            }
            $total=$this->register->eventSummary($s['event_id']);$h.='<details class="pos-panel" data-pos-event-summary><summary>Veranstaltung · alle Kassen</summary><p>'.$total['registers'].' Kassen · '.$total['open_registers'].' geöffnet · '.$total['closed_registers'].' abgeschlossen</p><p>Verkäufe nach Erstattungen: <strong>'.$this->money($total['paid_cents']).'</strong></p><p>Bar '.$this->money($total['cash_cents']).' · Wertgutschein '.$this->money($total['voucher_cents']).' · Karte / PayPal '.$this->money($total['card_cents']).'</p><p>Erstattet: '.$this->money($total['refunded_cents']).' · Anfangsbestände zählen nicht als Einnahmen.</p></details>';$h.='<details class="pos-panel"><summary>Verkäufe & Schichtabschluss</summary>';foreach($this->register->recent($shift) as $r)$h.='<p><a href="?view=pos&amp;shift='.$e($shift).'&amp;sale='.$e($r['id']).'">'.$e($r['created_at'].' · '.self::state($r['state'])).' · '.$this->money((int)$r['total_cents']).'</a></p>';if($s['state']==='open'&&$this->register->canManage())$h.=$this->form('close',['shift'=>$shift]).Html::input('counted','Bargeld einschließlich Anfangsbestand','','text','inputmode="decimal" required').'<button>Abschließen & einmalig in Handkasse übernehmen</button></form>';$h.='</details>';
        }
        if($this->register->canManage()){
            $events=[];foreach((new EventVouchers($this->db,$this->actor,$this->calendar))->events() as $event)$events[$event['id']]=$event['title'];$accounts=[];foreach((new Finance($this->db,$this->actor))->accounts() as $a)if($a['kind']==='cash'&&($a['active']??1))$accounts[$a['id']]=$a['name'];
            $h.='<section class="pos-panel pos-setup" id="pos-open"><h2>Kasse öffnen</h2>';
            if(!$accounts)$h.='<p class="pos-empty">Für Barzahlungen benötigst du eine Handkasse. Lege sie einmal im Bankbereich an und öffne anschließend hier die Kassenschicht.</p><a class="button" href="/vereinsverwaltung/?view=finance&amp;tab=bank&amp;new_account=1&amp;kind=cash">Handkasse anlegen</a>';
            elseif(!$events)$h.='<p class="pos-empty">Wähle zuerst eine Veranstaltung unter Tickets &amp; Gutscheine aus.</p><a class="button" href="/vereinsverwaltung/?view=portal&amp;tab=vouchers">Veranstaltung auswählen</a>';
            else $h.=$this->form('open').$this->stationFields().Html::select('event','Veranstaltung',$events,'').Html::select('account','Zielkonto für diese Handkasse',$accounts,'').Html::input('opening','Bargeld zu Schichtbeginn','0','text','inputmode="decimal" required').'<button>Schicht öffnen</button></form>';
            $h.='</section><details class="pos-panel" id="pos-products-settings"><summary>Artikeltasten anpassen</summary>'.$this->form('product').Html::input('label','Artikelbezeichnung','','text','required').Html::input('price','Preis','','text','inputmode="decimal" required').Html::input('color','Tastenfarbe','#225544','color').Html::select('kind','Artikelart',['goods'=>'Ware / Leistung','value-voucher'=>'Gekaufter Wertgutschein'],'goods').Html::select('sphere','Fachliche Sphäre',['ideell'=>'Ideeller Bereich','vermoegen'=>'Vermögensverwaltung','zweck'=>'Zweckbetrieb','wirtschaftlich'=>'Wirtschaftlicher Geschäftsbetrieb'],'wirtschaftlich').Html::input('benefit_label','Passende persönliche Vorteilsart (optional)').'<button>Artikeltaste speichern</button></form></details>';
        }
        if($this->register->canManage())foreach($this->register->editableProducts() as $p){$h.='<details class="pos-panel"><summary>'.$e($p['label']).' bearbeiten</summary>'.$this->form('product',['id'=>$p['id'],'version'=>$p['version']]).Html::input('label','Bezeichnung',$p['label']).Html::input('price','Preis',number_format($p['price_cents']/100,2,'.','')).Html::input('color','Tastenfarbe',$p['color'],'color').Html::select('kind','Art',['goods'=>'Ware / Leistung','value-voucher'=>'Wertgutschein'],$p['kind']).Html::select('sphere','Sphäre',['ideell'=>'Ideell','vermoegen'=>'Vermögen','zweck'=>'Zweckbetrieb','wirtschaftlich'=>'Wirtschaftlich'],$p['sphere']).Html::input('benefit_label','Persönliche Vorteilsart',$p['benefit_label']).Html::select('active','Verfügbarkeit',['1'=>'Aktiv','0'=>'Archiviert'],(string)$p['active']).'<button>Änderungen speichern</button></form></details>'; }
        return $this->shell($h.'</main>');
    }
    private function shell(string $body):string
    {return '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tickets &amp; Gutscheine · Kasse</title><link rel="stylesheet" href="/vereinsverwaltung/pos.css?v=1859"><link rel="stylesheet" href="/assets/tickets.css"><script defer src="/vereinsverwaltung/pos.js?v=1859"></script><script defer src="/assets/tickets.js"></script></head><body><a class="skip" href="#main">Zum Inhalt</a>'.$body.'</body></html>';}
    private function receipt(array $r):string
    {
        $e=Html::e(...);$brand=$r['brand']??[];$logo=($brand['logo_status']??'')==='frozen'?'<img alt="Vereinslogo auf dem Originalbeleg" style="max-width:160px;height:auto" src="data:image/png;base64,'. $e($brand['logo_png']).'">':'';$h='<article class="pos-receipt">'.$logo.'<h1>'.$e($r['club']['name']?:'Verein').'</h1><p>'.$e($r['club']['address']).'</p><h2>Originalbeleg '.$e($r['number']).'</h2><p>'.$e($r['created_at']).'</p><table><thead><tr><th>Artikel</th><th>Menge</th><th>Betrag</th></tr></thead><tbody>';foreach($r['lines'] as $p)$h.='<tr><td>'.$e($p['label']).'</td><td>'.$p['quantity'].'</td><td>'.$this->money($p['amount_cents']).'</td></tr>';$h.='</tbody></table><p>Rabatt '.$this->money($r['discount_cents']).' · Mitgliedervorteil '.$this->money($r['benefit_cents']).'</p><h3>Gesamt '.$this->money($r['total_cents']).'</h3><p>Bargeld '.$this->money($r['cash_cents']).' · Wertgutschein '.$this->money($r['voucher_cents']).'</p><p>Erhalten '.$this->money($r['received_cents']).' · Rückgeld '.$this->money($r['change_cents']).'</p>';if($r['external_payment'])$h.='<p>'.$e($r['external_payment']['provider'].' · '.$r['external_payment']['transaction_id']).' · '.$this->money($r['external_payment']['amount_cents']).'</p>';foreach($r['issued_vouchers'] as $v)$h.='<section><h3>Wertgutschein '.$this->money($v['face_cents']).'</h3><img class="pos-qr" width="240" height="240" alt="Wertgutschein-QR" src="data:image/png;base64,'.base64_encode(\Kulturhus\Native\Events\Tickets\Qr::valuePng($v['code'])).'"><p><code>'.$e($v['code']).'</code></p></section>';foreach($r['issued_tickets']??[]as$t)$h.='<section><h3>Eintrittsticket '.$t['ordinal'].'</h3><img class="pos-qr" width="240" height="240" alt="Eintrittsticket-QR" src="data:image/png;base64,'.base64_encode(\Kulturhus\Native\Events\Tickets\Qr::png($t['page_id'],$t['code'])).'"></section>';if(!empty($brand['qr_png']))$h.='<figure><img width="150" height="150" alt="QR-Code zur Vereinsdomain" src="data:image/png;base64,'.$e($brand['qr_png']).'"><figcaption>'.$e($r['club']['origin']).'</figcaption></figure>';return $h.'<button type="button" data-print>Beleg drucken</button></article>';
    }
}
